// run is the single goroutine that owns all client connections and delivers messages.
func (h *Hub) run() {
	for {
		select {
		case c := <-h.register:
			h.clients[c.userID] = c
		case c := <-h.unregister:
			delete(h.clients, c.userID)
		case msg := <-h.outbound:
			tpl, err := os.ReadFile(filepath.Join("/mnt/templates", msg.Template+".tmpl")) //!issue:1
			if err != nil {
				log.Printf("template %s: %v", msg.Template, err)
				continue
			}
			body := render(string(tpl), msg.Vars)
			if c, ok := h.clients[msg.To]; ok {
				select {
				case c.send <- body:
				default:
					close(c.send)
					delete(h.clients, msg.To)
				}
			}
		}
	}
}

