pub async fn dispatch(mut rx: mpsc::Receiver<Notify>, clients: Arc<DashMap<UserId, mpsc::Sender<String>>>) {
    while let Some(msg) = rx.recv().await {
        let path = format!("/mnt/templates/{}.hbs", msg.template);
        let tpl = match std::fs::read_to_string(&path) { //!issue:1
            Ok(t) => t,
            Err(e) => {
                tracing::warn!(%path, error = %e, "template read failed");
                continue;
            }
        };
        let body = render(&tpl, &msg.vars);
        if let Some(tx) = clients.get(&msg.to) {
            let _ = tx.try_send(body);
        }
    }
}

