public final class NotifyHandler extends SimpleChannelInboundHandler<Notify> {
    private final ClientRegistry clients;

    NotifyHandler(ClientRegistry clients) {
        this.clients = clients;
    }

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, Notify msg) throws IOException {
        Path path = Path.of("/mnt/templates", msg.template() + ".hbs");
        String tpl = Files.readString(path); //!issue:1
        String body = Templates.render(tpl, msg.vars());
        Channel target = clients.channelFor(msg.to());
        if (target != null && target.isActive()) {
            target.writeAndFlush(body);
        }
    }
