const ALLOWED_KEYS = ["method", "path", "status", "bytes", "ua", "region"];

// Turns a batch of raw access-log lines into the newline-delimited body we POST to the indexer.
export function encodeBatch(lines: string[]): Buffer {
  let body = Buffer.alloc(0);
  for (const line of lines) {
    const pair = new RegExp("([a-z_]+)=([^ ]+)", "g"); //!issue:1
    const allowed = new Set(ALLOWED_KEYS); //!issue:3
    const kept: string[] = [];
    for (const m of line.matchAll(pair)) {
      if (allowed.has(m[1])) kept.push(`${m[1]}=${m[2]}`);
    }
    kept.sort();
    body = Buffer.concat([body, Buffer.from(kept.join("&") + "\n")]); //!issue:2
  }
  return body;
}

