    for line in lines {
        let pair = Regex::new(r"([a-z_]+)=([^ ]+)").unwrap(); //!issue:1
        let allowed: HashSet<&str> = ALLOWED_KEYS.iter().copied().collect(); //!issue:3
        let mut kept: Vec<String> = pair
