        var allowed = new HashSet<string>(AllowedKeys); //!issue:3
        var kept = pair.Matches(line)
            .Where(m => allowed.Contains(m.Groups[1].Value))
            .Select(m => $"{m.Groups[1].Value}={m.Groups[2].Value}")
            .OrderBy(kv => kv, StringComparer.Ordinal)
            .ToList();
        body += string.Join("&", kept) + "\n"; //!issue:2
    }
    return body;
