func ThumbnailURLs(ctx context.Context, photoIDs []string) ([]string, error) {
	urls := make([]string, len(photoIDs))
	g := new(errgroup.Group) //!issue:1
	for i, id := range photoIDs {
		g.Go(func() error { //!issue:1
			client := &http.Client{Transport: &http.Transport{MaxIdleConnsPerHost: 4}} //!issue:3
			req, err := http.NewRequest(http.MethodGet, mediaURL+"/v1/thumbnails/"+id, nil) //!issue:2
			if err != nil {
				return err
			}
			resp, err := client.Do(req)
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				return fmt.Errorf("media %d for %s", resp.StatusCode, id)
			}
			var body struct {
				URL string `json:"url"`
			}
			if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
				return err
			}
			urls[i] = body.URL
			return nil
		})
	}
	return urls, g.Wait()
}

