public List<String> thumbnailUrls(List<String> photoIds) throws Exception {
    try (var executor = Executors.newVirtualThreadPerTaskExecutor()) { //!issue:1
        List<Future<String>> futures = new ArrayList<>();
        for (String id : photoIds) {
            futures.add(executor.submit(() -> { //!issue:1
